param([switch]$Open)
$ErrorActionPreference='Stop';$root=Split-Path -Parent (Split-Path -Parent $PSCommandPath);$need=@('PROTOCOL.md','CANONICAL-INPUT-TRANSFER.md','fixture/package-lock.json','fixture/database/schema/001_inventory.sql','prompts/S01.txt','prompts/S02.txt','execution-order.json','runner/Evaluate.ps1','calibration/CALIBRATION-SUMMARY.json','qualification/QUALIFICATION-SUMMARY.json','dispatch/CANDIDATE-SANDBOX-QUALIFICATION.json');$missing=$need|Where-Object{-not(Test-Path (Join-Path $root $_))};if($missing){throw "Missing gate inputs: $($missing-join ', ')"};$cal=Get-Content -Raw (Join-Path $root 'calibration/CALIBRATION-SUMMARY.json')|ConvertFrom-Json;$qual=Get-Content -Raw (Join-Path $root 'qualification/QUALIFICATION-SUMMARY.json')|ConvertFrom-Json;$sand=Get-Content -Raw (Join-Path $root 'dispatch/CANDIDATE-SANDBOX-QUALIFICATION.json')|ConvertFrom-Json;if($cal.result-ne'PASS'-or$qual.result-ne'PASS'-or$sand.result-ne'PASS'){throw 'Gate inputs are not green'};$state=Join-Path $root 'official-launch-state.json';if($Open){$s=Get-Content -Raw $state|ConvertFrom-Json;if($s.gate-ne'CLOSED'-or$s.officialLaunchCount-ne0){throw 'Gate cannot be reopened'};$s.gate='OPEN';$s|ConvertTo-Json -Depth 6|Set-Content $state};Get-Content -Raw $state
